public class Solution {
    interface Cache {
        String get(String chave);
        void setex(String chave, long ttlSegundos, String valor);
        void del(String chave);
    }

    interface ProdutoRepositorio {
        String buscar(String id);
        void salvar(String id, String valor);
    }

    static class ProdutoService {
        private final Cache cache;
        private final ProdutoRepositorio repo;
        private final long ttlSegundos;
        private long hits = 0;
        private long misses = 0;

        ProdutoService(Cache cache, ProdutoRepositorio repo, long ttlSegundos) {
            if (cache == null || repo == null) throw new IllegalArgumentException("dependencias obrigatorias");
            if (ttlSegundos <= 0) throw new IllegalArgumentException("ttl invalido");
            this.cache = cache;
            this.repo = repo;
            this.ttlSegundos = ttlSegundos;
        }

        String buscar(String id) {
            exigirId(id);
            String chave = "produto:" + id;
            String emCache = cache.get(chave);
            if (emCache != null) {
                hits++;
                return emCache;
            }
            misses++;
            String doBanco = repo.buscar(id);
            if (doBanco != null) cache.setex(chave, ttlSegundos, doBanco);
            return doBanco;
        }

        void atualizar(String id, String novoValor) {
            exigirId(id);
            if (novoValor == null) throw new IllegalArgumentException("valor obrigatorio");
            repo.salvar(id, novoValor);
            cache.del("produto:" + id);
        }

        long cacheHits() { return hits; }
        long cacheMisses() { return misses; }

        double hitRatio() {
            long total = hits + misses;
            return total == 0 ? 0.0 : (double) hits / total;
        }

        private void exigirId(String id) {
            if (id == null || id.isBlank()) throw new IllegalArgumentException("id obrigatorio");
        }
    }
}

