import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class SolutionTest {
    static class CacheFake implements Solution.Cache {
        final Map<String, String> valores = new HashMap<>();
        final Map<String, Long> expiraEm = new HashMap<>();
        final List<String> eventos;
        long agora = 0;

        CacheFake(List<String> eventos) { this.eventos = eventos; }

        public String get(String chave) {
            Long exp = expiraEm.get(chave);
            if (exp != null && agora >= exp) {
                valores.remove(chave);
                expiraEm.remove(chave);
            }
            return valores.get(chave);
        }

        public void setex(String chave, long ttl, String valor) {
            eventos.add("cache:set:" + chave);
            valores.put(chave, valor);
            expiraEm.put(chave, agora + ttl);
        }

        public void del(String chave) {
            eventos.add("cache:del:" + chave);
            valores.remove(chave);
            expiraEm.remove(chave);
        }

        void avancar(long segundos) { agora += segundos; }
    }

    static class RepoFake implements Solution.ProdutoRepositorio {
        final Map<String, String> dados = new HashMap<>();
        final List<String> eventos;
        int buscas = 0;

        RepoFake(List<String> eventos) { this.eventos = eventos; }

        public String buscar(String id) {
            buscas++;
            eventos.add("repo:buscar:" + id);
            return dados.get(id);
        }

        public void salvar(String id, String valor) {
            eventos.add("repo:salvar:" + id);
            dados.put(id, valor);
        }
    }

    @Test void cacheMissDepoisHit() {
        var eventos = new ArrayList<String>();
        var cache = new CacheFake(eventos);
        var repo = new RepoFake(eventos);
        repo.dados.put("p1", "caneta");
        var service = new Solution.ProdutoService(cache, repo, 60);

        assertEquals("caneta", service.buscar("p1"));
        assertEquals("caneta", service.buscar("p1"));
        assertEquals(1, repo.buscas);
        assertEquals(1, service.cacheHits());
        assertEquals(1, service.cacheMisses());
        assertEquals(0.5, service.hitRatio());
        assertEquals("caneta", cache.valores.get("produto:p1"));
    }

    @Test void ttlExpiraEBuscaDeNovo() {
        var eventos = new ArrayList<String>();
        var cache = new CacheFake(eventos);
        var repo = new RepoFake(eventos);
        repo.dados.put("p1", "caneta");
        var service = new Solution.ProdutoService(cache, repo, 10);

        service.buscar("p1");
        cache.avancar(11);
        service.buscar("p1");
        assertEquals(2, repo.buscas);
        assertEquals(0, service.cacheHits());
        assertEquals(2, service.cacheMisses());
    }

    @Test void atualizacaoInvalidaDepoisDeSalvar() {
        var eventos = new ArrayList<String>();
        var cache = new CacheFake(eventos);
        var repo = new RepoFake(eventos);
        repo.dados.put("p1", "antigo");
        var service = new Solution.ProdutoService(cache, repo, 60);
        service.buscar("p1");

        eventos.clear();
        service.atualizar("p1", "novo");

        assertEquals(List.of("repo:salvar:p1", "cache:del:produto:p1"), eventos);
        assertEquals("novo", service.buscar("p1"));
    }

    @Test void ausenciaNaoEhCacheada() {
        var eventos = new ArrayList<String>();
        var cache = new CacheFake(eventos);
        var repo = new RepoFake(eventos);
        var service = new Solution.ProdutoService(cache, repo, 60);

        assertNull(service.buscar("x"));
        assertNull(service.buscar("x"));
        assertEquals(2, repo.buscas);
        assertNull(cache.valores.get("produto:x"));
    }

    @Test void metricasSemConsultas() {
        var service = new Solution.ProdutoService(
            new CacheFake(new ArrayList<>()), new RepoFake(new ArrayList<>()), 60);
        assertEquals(0.0, service.hitRatio());
        assertEquals(0, service.cacheHits());
    }

    @Test void validacoes() {
        assertThrows(IllegalArgumentException.class,
            () -> new Solution.ProdutoService(new CacheFake(new ArrayList<>()),
                new RepoFake(new ArrayList<>()), 0));
        var service = new Solution.ProdutoService(
            new CacheFake(new ArrayList<>()), new RepoFake(new ArrayList<>()), 60);
        assertThrows(IllegalArgumentException.class, () -> service.buscar(""));
        assertThrows(IllegalArgumentException.class, () -> service.atualizar("p1", null));
    }
}
